			return nil
		}
		state, buildErr := buildReplicatedSessionState(lockCtx, source, rec, meta, ev.Repo, ev.Files)
		if buildErr != nil {
			return buildErr
		}
		if saveErr := targetStore.Save(lockCtx, state); saveErr != nil {
			return fmt.Errorf("save target session state: %w", saveErr)
		}
		return nil
	})
