	repoEnabledWithOrigin(t)
	writeUserSettings(t, `{"global":{"enabled":false}}`)
	settingsPath := filepath.Join(os.Getenv("ENTIRE_CONFIG_DIR"), "settings.json")
	before, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Fatal(err)
	}
