	if os.Getenv(bindingReplayEnv) == "1" {
		return os.Getenv(bindingReplayPrimaryEnv) == "1"
	}
	collector := bindingTurnCollectorFromContext(ctx)
	_, primary := collector.replaySnapshot()
	return primary == "" || primary == currentCommonDir
}
